/* PWADC Security Operations Suite v3.3.0.5 | module: reports-governance */
function reportMoney(v){let n=Number(v)||0;return '$'+n.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}
function reportNumber(v,d=0){let n=Number(v)||0;return n.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d})}
function reportDate(){return new Date().toLocaleString()}
function activeRosterForReports(){return rosterActiveEmployees().slice().sort((a,b)=>fullName(a).localeCompare(fullName(b)))}
function reportMetrics(){const active=activeRosterForReports();const sched=scheduleMetrics();const scheduleAuthority=scheduleAuthorityModel(sched);const cov=scheduleAuthority;const classes=employmentClassCounts(active);const flags=computeFlags().filter(f=>!f.addressed);const training=trainingReadinessMetrics(active);const uniformItems=(typeof getUniformItems==='function')?getUniformItems('all'):[];const uniformNeeded=uniformItems.filter(i=>i.status==='needed').length;const uniformOrdered=uniformItems.filter(i=>i.status==='ordered').length;const uniformIssued=uniformItems.filter(i=>i.status==='issued').length;const uniformLostDamaged=uniformItems.filter(i=>['lost','damaged'].includes(i.status)).length;const uniformDueSoon=uniformItems.filter(i=>['due-soon','past-due'].includes(replacementDueClass(i.replacementDue))).length;const openTasks=(tasks.tasks||[]).filter(t=>!['Complete','Archived','On Hold'].includes(String(t.status||''))).length;return{active,sched,cov,scheduleAuthority,classes,flags,training,uniformItems,uniformNeeded,uniformOrdered,uniformIssued,uniformLostDamaged,uniformDueSoon,openTasks}}
function reportWeekStart(){const base=parseISO(gridEnd||new Date().toISOString().slice(0,10));base.setDate(base.getDate()-base.getDay());return base;}
function isoFromWeekDay(idx){const d=reportWeekStart();d.setDate(d.getDate()+Number(idx||0));return toISO(d);}
function attendanceEmployeeForScheduleCell(raw){const re=findRosterByScheduleName(raw);if(re)return attendanceEmployeeForRoster(re);const cleaned=schedulePersonName(raw);if(!cleaned)return null;const cp=attendanceNameParts(cleaned);const ck=compactPersonKey(cp.last,cp.first);return (attendance.employees||[]).find(a=>attendanceEmpKeyFromName(a.name)===ck)||null;}
const ATTENDANCE_COVERED_CODES=new Set(['P','T','E','AL','V','FL','LE']);
const ATTENDANCE_MISSED_CODES=new Set(['U','UE','CO','NCNS','O']);
function scheduleAttendanceStatus(raw,dayIdx){const ae=attendanceEmployeeForScheduleCell(raw);if(!ae)return{code:'',status:'No attendance match'};const date=isoFromWeekDay(dayIdx);const code=((attendance.attendance||{})[ae.id]||{})[date]||'';if(!code)return{code:'',status:'No entry'};if(ATTENDANCE_COVERED_CODES.has(code))return{code,status:code==='T'?'Tardy / covered':'Covered'};if(ATTENDANCE_MISSED_CODES.has(code))return{code,status:'Missed'};return{code,status:'Other'};}
function scheduleAuthorityModel(metrics=scheduleMetrics()){
  const rows=[];
  const totals={requiredHours:0,scheduledHours:0,openHours:0,openPosts:0,overHours:0,loadedCost:metrics.loadedCost||0,attendanceCoveredHours:0,attendanceMissedHours:0,attendanceMissingHours:0,attendanceTardyHours:0,attendanceIssueCount:0,highestRisk:'None'};
  for(const row of (roster.schedule||[])){
    const hrs=Number(row.hrs||8);let required=0,scheduled=0,open=0,openPosts=0,covered=0,missed=0,missing=0,tardy=0,issues=0;const activeDays=[];
    for(let dayIdx=0;dayIdx<(row.days||[]).length;dayIdx++){
      const val=(row.days||[])[dayIdx];if(scheduleCellIsBlank(val))continue;required+=hrs;activeDays.push(DAYS[dayIdx]);
      if(scheduleCellIsOpen(val)){open+=hrs;openPosts++;continue;}
      scheduled+=hrs;const att=scheduleAttendanceStatus(val,dayIdx);
      if(att.status==='Covered'||att.status==='Tardy / covered'){covered+=hrs;if(att.code==='T'){tardy+=hrs;issues++;}}
      else if(att.status==='Missed'){missed+=hrs;issues++;}
      else if(att.status==='No entry'||att.status==='No attendance match'){missing+=hrs;issues++;}
    }
    if(required<=0)continue;
    let risk='Covered';if(open>0)risk='Open/Pending';if(scheduled===0&&required>0)risk='No scheduled coverage';if(missed>0||missing>0)risk=open>0?'Open/Pending + Attendance Issues':'Attendance Issues';
    const area=(row.section||'Unassigned')+' · '+(row.post||'Post');
    rows.push({area,section:row.section||'Unassigned',post:row.post||'',dayLabel:activeDays.join(', '),requiredHours:required,scheduledHours:scheduled,openHours:open,overHours:0,openPosts,requiredHeadcount:'Schedule',hoursPerPost:hrs,scheduledSlots:scheduled?scheduled/hrs:0,attendanceCoveredHours:covered,attendanceMissedHours:missed,attendanceMissingHours:missing,attendanceTardyHours:tardy,attendanceIssueCount:issues,risk,notes:'Schedule-authority: named cells count as scheduled; Open/Pending count as unfilled.'});
    totals.requiredHours+=required;totals.scheduledHours+=scheduled;totals.openHours+=open;totals.openPosts+=openPosts;totals.attendanceCoveredHours+=covered;totals.attendanceMissedHours+=missed;totals.attendanceMissingHours+=missing;totals.attendanceTardyHours+=tardy;totals.attendanceIssueCount+=issues;
  }
  const worst=rows.slice().sort((a,b)=>(b.openHours+b.attendanceMissedHours+b.attendanceMissingHours)-(a.openHours+a.attendanceMissedHours+a.attendanceMissingHours))[0];
  totals.highestRisk=worst?worst.area:'None';
  return{rows,total:totals,source:'schedule-authority'};
}

function reportKpis(items){return `<div class="report-kpis">${items.map(i=>`<div class="report-kpi"><strong>${esc(i.value)}</strong><span>${esc(i.label)}</span></div>`).join('')}</div>`}
function reportTable(headers,rows){return `<table class="report-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${String(c??'')}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">No records found.</td></tr>`}</tbody></table>`}
function reportMethodologyNote(){return `<div class="report-method"><strong>HPW Methodology:</strong> HPW is calculated from the published schedule. Named employee cells count as Named Scheduled HPW. Open and Pending cells count as Open/Pending HPW. Closed and blank cells are excluded. Schedule Required HPW equals Named Scheduled HPW plus Open/Pending HPW.</div>`}
function reportAttendanceLegend(){return `<div class="report-method"><strong>Attendance Legend:</strong> Covered = P, E, AL, V, FL, LE. Issue/Missed = U, UE, CO, NCNS. Tardy = T and is still counted as covered HPW with a tardy flag. No Entry means the scheduled employee did not have an attendance record for that scheduled date.</div>`}
function reportDataConfidence(m){m=m||reportMetrics();const scheduleRecords=Object.values(m.sched.sections||{}).reduce((n,x)=>n+Number(x.rows||0),0);const openCells=Number(m.cov.total.openPosts||0);const matched=Number(m.cov.total.attendanceCoveredHours||0)+Number(m.cov.total.attendanceMissedHours||0);const missing=Number(m.cov.total.attendanceMissingHours||0);return `<div class="report-section report-compact"><h2>Data Confidence</h2>${reportKpis([{label:'Schedule Rows Counted',value:scheduleRecords},{label:'Open/Pending Cells',value:openCells},{label:'Attendance HPW Matched',value:matched},{label:'Attendance No-Entry HPW',value:missing}])}</div>`}
function reportRangeMeta(){const a=reportDateStart||document.getElementById('reportDateStart')?.value||'';const b=reportDateEnd||document.getElementById('reportDateEnd')?.value||'';if(a&&b)return '<br>Date range: '+esc(fmtDate(a))+' through '+esc(fmtDate(b));if(a)return '<br>Date range start: '+esc(fmtDate(a));if(b)return '<br>Date range end: '+esc(fmtDate(b));return '<br>Date range: Current available data';}
function reportDoc(title,subtitle,body,orientation='portrait'){const meta=`Generated ${reportDate()}<br>Generated by ${esc(currentUserName())}<br>Version v3.3.0.5${reportRangeMeta()}`;return `<div class="report-doc ${orientation==='landscape'?'landscape':''}"><div class="report-header"><div><div class="report-brand">PWADC Security Operations Suite</div><h1>${esc(title)}</h1><div class="report-note">${esc(subtitle||'')}</div></div><div class="report-meta">${meta}</div></div>${body}<div class="report-footer">Data source: PWADC Security Operations Suite shared JSON files. Pay detail visibility follows the signed-in user role. Date range controls are included where applicable and reports identify their methodology in the body when HPW or attendance interpretation is used.</div></div>`}
function reportShell(title,subtitle,body,orientation='portrait'){return `<div class="report-print-toolbar"><div><strong>${esc(title)}</strong><div class="report-note">${esc(subtitle||'Professional management report')}</div></div><div><button onclick="window.print()">Print</button><button onclick="document.getElementById('reportPrintOverlay').remove()">Close</button></div></div>${reportDoc(title,subtitle,body,orientation)}`}
function reportPrintStyles(orientation='portrait'){return `<style>@page{size:${orientation==='landscape'?'landscape':'portrait'};margin:.35in}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#111;background:#fff;margin:0;padding:0}.report-doc{font-family:Arial,Helvetica,sans-serif;color:#111;background:#fff;padding:0;line-height:1.35}.report-header{border-bottom:3px solid #222;padding-bottom:12px;margin-bottom:18px;display:flex;justify-content:space-between;gap:16px}.report-brand{font-size:12px;text-transform:uppercase;letter-spacing:1px;color:#555;font-weight:700}h1{font-size:22pt;margin:4px 0 0 0}.report-meta{font-size:10px;color:#555;text-align:right}.report-note{font-size:11px;color:#555;line-height:1.4}.report-section{margin:14px 0}.report-section:not(.report-allow-break){break-inside:auto;page-break-inside:auto}.report-compact{break-inside:avoid;page-break-inside:avoid}.report-method{border:1px solid #aaa;border-left:5px solid #555;background:#f8f8f8;padding:8px 10px;margin:10px 0;font-size:10.5pt;line-height:1.35}h2{font-size:13pt;text-transform:uppercase;letter-spacing:.8px;border-bottom:1px solid #bbb;padding-bottom:5px;margin:0 0 8px 0}.report-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(135px,1fr));gap:8px}.report-kpi{border:1px solid #bbb;padding:9px;border-radius:6px;background:#f7f7f7}.report-kpi strong{display:block;font-size:18px}.report-kpi span{display:block;font-size:9px;text-transform:uppercase;color:#555;font-weight:700;letter-spacing:.5px}.report-table{border-collapse:collapse;width:100%;font-size:10pt;page-break-inside:auto}.report-table thead{display:table-header-group}.report-table tr{page-break-inside:avoid;break-inside:avoid}.report-table th{background:#eee;border:1px solid #aaa;text-align:left;padding:6px;font-size:9.5pt}.report-table td{border:1px solid #bbb;padding:5px;vertical-align:top}.report-risk{font-weight:700}.report-risk.bad{color:#9b1c1c}.report-summary{border:1px solid #aaa;border-left:5px solid #222;padding:10px;background:#fafafa}.report-footer{font-size:9px;color:#555;border-top:1px solid #bbb;margin-top:18px;padding-top:8px}.printbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;padding:10px;border:1px solid #bbb;background:#f7f7f7}.printbar button{padding:7px 12px;font-weight:700}@media print{.printbar{display:none!important}body{padding:0}.report-doc{padding:0}}



</style>`}
function showReport(title,subtitle,body,orientation='portrait',autoPrint=false){const doc=reportDoc(title,subtitle,body,orientation);const generated=reportDate();const w=window.open('','_blank');if(w){w.document.open();w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title>${reportPrintStyles(orientation)}</head><body><div class="printbar"><div><strong>${esc(title)}</strong><div class="report-note">${esc(subtitle||'Professional management report')}</div><div class="report-note"><strong>Preview mode:</strong> review page breaks and layout, then use Print / Save PDF when ready. Generated ${esc(generated)}.</div></div><div><button onclick="window.print()">Print / Save PDF</button><button onclick="window.close()">Close Preview</button></div></div>${doc}</body></html>`);w.document.close();setTimeout(()=>{try{w.focus();if(autoPrint)w.print();}catch(_){ }},250);return;}document.getElementById('reportPrintOverlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="print-overlay report-print" id="reportPrintOverlay">${reportShell(title,subtitle,body,orientation)}</div>`);if(autoPrint)setTimeout(()=>window.print(),180)}
function openReportWindow(docHtml,autoPrint=false,orientation='portrait'){const title=(String(docHtml||'').match(/<h1[^>]*>(.*?)<\/h1>/i)||[])[1]||'PWADC Report';const w=window.open('','_blank');if(w){w.document.open();w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${esc(title)}</title>${reportPrintStyles(orientation)}</head><body><div class="printbar"><div><strong>${esc(title)}</strong><div class="report-note">Preview mode: review layout, then print or save PDF.</div></div><div><button onclick="window.print()">Print / Save PDF</button><button onclick="window.close()">Close Preview</button></div></div>${docHtml}</body></html>`);w.document.close();setTimeout(()=>{try{w.focus();if(autoPrint)w.print();}catch(_){ }},200);return;}document.getElementById('reportPrintOverlay')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="print-overlay report-print" id="reportPrintOverlay"><div class="report-print-toolbar"><div><strong>${esc(title)}</strong><div class="report-note">Preview fallback</div></div><div><button onclick="window.print()">Print</button><button onclick="document.getElementById('reportPrintOverlay').remove()">Close</button></div></div>${docHtml}</div>`);if(autoPrint)setTimeout(()=>window.print(),180)}

function coverageRowsForReport(onlyGaps=false){const m=reportMetrics();let rows=m.cov.rows.slice();if(onlyGaps)rows=rows.filter(r=>r.openHours>0||r.attendanceMissedHours>0||r.attendanceMissingHours>0||['Open/Pending','No scheduled coverage','Attendance Issues','Open/Pending + Attendance Issues'].includes(r.risk));return rows.map(r=>[esc(r.area),esc(r.section),esc(r.post||'All'),esc(r.dayLabel||''),r.requiredHours,r.scheduledHours,`<span class="report-risk ${r.openHours>0?'bad':''}">${r.openHours}</span>`,r.attendanceCoveredHours||0,r.attendanceMissedHours||0,r.attendanceMissingHours||0,esc(r.risk),esc(r.notes||'')])}
function reportWeeklyStaffing(autoPrint=false){const m=reportMetrics();let body=`<div class="report-section report-compact"><div class="report-summary"><strong>Executive Summary:</strong> This report uses the published weekly schedule as the staffing authority. Security has ${m.active.length} active roster employees. Schedule Required HPW is ${m.cov.total.requiredHours}; Named Scheduled HPW is ${m.cov.total.scheduledHours}; Open/Pending HPW is ${m.cov.total.openHours}. Attendance Covered HPW for the report week is ${m.cov.total.attendanceCoveredHours}; Attendance Missed / No-Entry HPW is ${Number(m.cov.total.attendanceMissedHours||0)+Number(m.cov.total.attendanceMissingHours||0)}. Highest risk area: ${esc(m.cov.total.highestRisk||'None')}.</div>${reportMethodologyNote()}${reportAttendanceLegend()}</div><div class="report-section report-compact">${reportKpis([{label:'Active Headcount',value:m.active.length},{label:'FT Pig',value:m.classes.FT||0},{label:'PT Pig',value:m.classes.PT||0},{label:'TempToHire',value:m.classes.TempToHire||0},{label:'Schedule Required HPW',value:m.cov.total.requiredHours},{label:'Named Scheduled HPW',value:m.cov.total.scheduledHours},{label:'Open/Pending HPW',value:m.cov.total.openHours},{label:'Attendance Covered HPW',value:m.cov.total.attendanceCoveredHours},{label:'Attendance Missed HPW',value:m.cov.total.attendanceMissedHours},{label:'No Entry HPW',value:m.cov.total.attendanceMissingHours}])}</div>${reportDataConfidence(m)}<div class="report-section report-allow-break"><h2>Schedule Authority Detail</h2>${reportTable(['Area','Section','Post','Days','Schedule Required HPW','Named Scheduled HPW','Open/Pending HPW','Attendance Covered HPW','Attendance Missed HPW','No Entry HPW','Risk','Notes'],coverageRowsForReport(false))}</div><div class="report-section report-compact"><h2>Operational Risk Snapshot</h2>${reportKpis([{label:'Open Discipline Thresholds',value:m.flags.length},{label:'Training Issues',value:m.training.issueCount},{label:'Uniform Items Needed',value:m.uniformNeeded},{label:'Open Tasks',value:m.openTasks},{label:'OT People',value:m.sched.overtimePeople},{label:'OT Exposure HPW',value:m.sched.overtimeHours}])}</div>`;showReport('Weekly Staffing Report','Schedule-authority staffing, attendance comparison, and operating gaps',''+body,'landscape',autoPrint)}
function reportLaborCost(autoPrint=false){const m=reportMetrics();if(!canViewLaborSummary()){toast('Labor cost reports are restricted');return;}let kpis=[{label:'Loaded Weekly Cost',value:reportMoney(m.sched.loadedCost)},{label:'Loaded Monthly Run Rate',value:reportMoney(m.sched.loadedCost*Number(settings.monthlyMultiplier||4.333))},{label:'Loaded Annual Run Rate',value:reportMoney(m.sched.loadedCost*Number(settings.annualMultiplier||52))},{label:'FTE Equivalent',value:reportNumber(m.sched.fte,2)},{label:'Schedule Required HPW',value:m.cov.total.requiredHours},{label:'Named Scheduled HPW',value:m.cov.total.scheduledHours},{label:'Open/Pending HPW',value:m.cov.total.openHours}];if(canViewIndividualPay()){kpis.unshift({label:'Base Weekly Cost',value:reportMoney(m.sched.cost)});kpis.push({label:'Loaded Add-On',value:reportMoney(m.sched.loadedCost-m.sched.cost)});}let sectionRows=Object.values(m.sched.sections).map(x=>canViewIndividualPay()?[esc(x.section),x.assignedHours,x.requiredHours,x.openHours,reportMoney(x.cost),reportMoney(x.loadedCost)]:[esc(x.section),x.assignedHours,x.requiredHours,x.openHours,reportMoney(x.loadedCost)]);let body=`<div class="report-section report-compact"><div class="report-summary"><strong>Executive Summary:</strong> Loaded weekly labor run rate is ${reportMoney(m.sched.loadedCost)}. Cost uses named schedule assignments only. Open/Pending cells are treated as unfilled and do not add employee payroll cost. ${canViewIndividualPay()?'This Admin view includes individual cost detail.':'This Supervisor view excludes individual pay rates and employee-level payroll cost.'}</div>${reportMethodologyNote()}</div><div class="report-section report-compact">${reportKpis(kpis)}</div>${reportDataConfidence(m)}<div class="report-section report-allow-break"><h2>Cost by Section</h2>${reportTable(canViewIndividualPay()?['Section','Named Scheduled HPW','Schedule Required HPW','Open/Pending HPW','Base Cost','Loaded Cost']:['Section','Named Scheduled HPW','Schedule Required HPW','Open/Pending HPW','Loaded Cost'],sectionRows)}</div>`;if(canViewIndividualPay()){const costRows=employeeCostRows(m.active).filter(r=>Number(r.hours||0)>0).map(r=>[esc(r.employee),esc(r.class),r.hours,reportMoney(r.rate),reportMoney(r.baseWeek),reportMoney(r.loadedWeek),reportMoney(r.loadedYear)]);body+=`<div class="report-section"><h2>Employee Cost Detail</h2>${reportTable(['Employee','Class','Named Scheduled HPW','Rate','Base Week','Loaded Week','Loaded Year'],costRows)}</div>`;}showReport('Labor Cost Summary','Schedule-authority base and loaded labor cost with role-based pay visibility',body,'landscape',autoPrint)}
function reportCoverageGap(autoPrint=false){const m=reportMetrics();let gapRows=coverageRowsForReport(true);let body=`<div class="report-section report-compact"><div class="report-summary"><strong>Executive Summary:</strong> Schedule-authority review shows ${m.cov.total.openPosts} Open/Pending post(s), ${m.cov.total.openHours} Open/Pending HPW, and ${Number(m.cov.total.attendanceMissedHours||0)+Number(m.cov.total.attendanceMissingHours||0)} Attendance Missed / No-Entry HPW. Highest risk area: ${esc(m.cov.total.highestRisk||'None')}.</div>${reportMethodologyNote()}${reportAttendanceLegend()}</div><div class="report-section report-compact">${reportKpis([{label:'Open/Pending Posts',value:m.cov.total.openPosts},{label:'Open/Pending HPW',value:m.cov.total.openHours},{label:'Attendance Missed HPW',value:m.cov.total.attendanceMissedHours},{label:'No Entry HPW',value:m.cov.total.attendanceMissingHours},{label:'Highest Risk Area',value:m.cov.total.highestRisk||'None'}])}</div>${reportDataConfidence(m)}<div class="report-section report-allow-break"><h2>Open / Missed Schedule Items</h2>${reportTable(['Area','Section','Post','Days','Schedule Required HPW','Named Scheduled HPW','Open/Pending HPW','Attendance Covered HPW','Attendance Missed HPW','No Entry HPW','Risk','Notes'],gapRows)}</div>`;showReport('Coverage Gap Report','Schedule Open/Pending cells and attendance exceptions',body,'landscape',autoPrint)}
function attendanceReportRows(daysBack){const end=parseISO(gridEnd||new Date().toISOString().slice(0,10));const start=new Date(end);start.setDate(start.getDate()-Number(daysBack||30)+1);let counts={};let issuePeople={};for(const emp of activeAttendanceEmployees()){let d=new Date(start);while(d<=end){let iso=toISO(d);let c=getCode(emp.id,iso);if(c){counts[c]=(counts[c]||0)+1;if(OCC_CODES.has(c)){issuePeople[emp.name]=(issuePeople[emp.name]||0)+1;}}d.setDate(d.getDate()+1);}}return{counts,issuePeople,start:toISO(start),end:toISO(end)}}
function reportAttendanceSummary(autoPrint=false){const r30=attendanceReportRows(30),r90=attendanceReportRows(90);const codeRows=CODES.map(c=>[c[0],esc(c[1]),r30.counts[c[0]]||0,r90.counts[c[0]]||0]);const issueRows=Object.entries(r90.issuePeople).sort((a,b)=>b[1]-a[1]).slice(0,25).map(([n,c])=>[esc(n),c]);let body=`<div class="report-section"><div class="report-summary"><strong>Executive Summary:</strong> Attendance summary covers ${esc(r90.start)} through ${esc(r90.end)} with a 30-day and 90-day comparison. Issue codes include T, U, UE, CO, and NCNS.</div></div><div class="report-section"><h2>Code Counts</h2>${reportTable(['Code','Description','Last 30 Days','Last 90 Days'],codeRows)}</div><div class="report-section"><h2>Top 90-Day Issue Counts</h2>${reportTable(['Employee','Issue Code Count'],issueRows)}</div>`;showReport('Attendance Summary Report','30-day and 90-day attendance code review',body,'portrait',autoPrint)}
function reportTrainingReadiness(autoPrint=false){const active=activeRosterForReports();const topics=activeTrainingTopics().filter(t=>t.required!==false);let rows=[];let totalRequired=0,current=0,missing=0,expired=0,expiring=0;for(const e of active){const ready=trainingReadinessForEmployee(e);totalRequired+=ready.total;current+=ready.current;missing+=ready.missing;expired+=ready.expired;expiring+=ready.expiring;for(const r of ready.rows){if(trainingStatusIssue(r.status)){rows.push([esc(fullName(e)),esc(e.shift||''),esc(r.topic.name||''),esc(trainingRequirementLabel(r.topic.requirementGroup||'All')),esc(r.status),esc(fmtDate(r.completed||'')),esc(fmtDate(r.due||'')),esc(r.trainer||'')]);}}}const score=totalRequired?Math.round((current/totalRequired)*100):100;const postM=postReadinessSummaryMetrics(active);const shiftRows=Object.entries(active.reduce((m,e)=>{const key=trainingShiftLabel(trainingShiftGroup(e.shift));const r=trainingReadinessForEmployee(e);m[key]=m[key]||{emps:0,total:0,current:0,missing:0,expired:0,expiring:0};m[key].emps++;m[key].total+=r.total;m[key].current+=r.current;m[key].missing+=r.missing;m[key].expired+=r.expired;m[key].expiring+=r.expiring;return m;},{})).map(([shift,x])=>[esc(shift),x.emps,x.total,x.total?Math.round((x.current/x.total)*100)+'%':'100%',x.missing,x.expired,x.expiring]);const postRows=trainingPostGroups().map(g=>{let ready=0,issues=0,notReq=0;for(const e of active){const r=postReadinessForEmployee(e,g.key);if(r.status==='Not Required')notReq++;else if(r.status==='Ready')ready++;else issues++;}return[esc(g.label),ready,issues,notReq];});let body=`<div class="report-section"><div class="report-summary"><strong>Executive Summary:</strong> Training readiness is ${score}%. ${rows.length} required training exception(s) need review. ${postM.notReady} employee(s) have post-readiness issues.</div></div><div class="report-section">${reportKpis([{label:'Active Employees',value:active.length},{label:'Required Topics',value:topics.length},{label:'Readiness Score',value:score+'%'},{label:'Missing',value:missing},{label:'Expired',value:expired},{label:'Expiring Soon',value:expiring},{label:'Not Post-Ready',value:postM.notReady}])}</div><div class="report-section"><h2>Readiness by Shift</h2>${reportTable(['Shift','Employees','Required Items','Readiness','Missing','Expired','Expiring'],shiftRows)}</div><div class="report-section"><h2>Readiness by Post Type</h2>${reportTable(['Post Type','Ready','Issues','Not Required'],postRows)}</div><div class="report-section"><h2>Training Readiness Exceptions</h2>${reportTable(['Employee','Shift','Topic','Required For','Status','Completed','Expires','Trainer'],rows)}</div><div class="report-section"><h2>Active Training Requirements</h2>${reportTable(['Topic','Required For','Expiration','Warning','Active'],topics.map(t=>[esc(t.name),esc(trainingRequirementLabel(t.requirementGroup||'All')),esc(intervalLabel(t.intervalDays)),esc((Number(t.warningDays||30))+' days'),t.active===false?'No':'Yes']))}</div>`;showReport('Training Readiness Report','Role/post-based required training, post readiness, expiration exposure, and readiness exceptions',body,'landscape',autoPrint)}
function reportUniformStatus(autoPrint=false){const items=(typeof getUniformItems==='function')?getUniformItems('all'):[];const exceptions=items.filter(i=>!['issued','returned','retired'].includes(i.status));const due=items.filter(i=>['due-soon','past-due'].includes(replacementDueClass(i.replacementDue)));const value=items.filter(i=>['issued','lost','damaged'].includes(i.status)).reduce((n,i)=>n+(Number(i.cost||0)*Number(i.qty||1)),0);const rows=exceptions.map(i=>[esc(i.employee),esc(i.rank),esc(i.shift),esc(titleCase(i.item)),esc(i.size),uniformStatusBadge(i.status),i.qty,esc(fmtDate(i.replacementDue||'')),canViewIndividualPay()?reportMoney(Number(i.cost||0)*Number(i.qty||1)):'',esc(i.notes||'')]);let body=`<div class="report-section"><div class="report-summary"><strong>Executive Summary:</strong> ${exceptions.length} uniform exception(s) require follow-up. ${due.length} item(s) are replacement due or past due. ${canViewIndividualPay()?'Estimated issued/lost/damaged uniform value is '+reportMoney(value)+'.':'Cost/value detail is restricted to Admin.'}</div></div><div class="report-section">${reportKpis([{label:'Needed',value:items.filter(i=>i.status==='needed').length},{label:'Ordered',value:items.filter(i=>i.status==='ordered').length},{label:'Issued',value:items.filter(i=>i.status==='issued').length},{label:'Lost / Damaged',value:items.filter(i=>['lost','damaged'].includes(i.status)).length},{label:'Replacement Due',value:due.length}].concat(canViewIndividualPay()?[{label:'Uniform Value',value:reportMoney(value)}]:[]))}</div><div class="report-section"><h2>Uniform Exceptions</h2>${reportTable(canViewIndividualPay()?['Employee','Rank','Shift','Item','Size','Status','Qty','Replace Due','Value','Notes']:['Employee','Rank','Shift','Item','Size','Status','Qty','Replace Due','Notes'],canViewIndividualPay()?rows:rows.map(r=>r.filter((_,idx)=>idx!==8)))}</div><div class="report-section"><h2>Replacement Due / Past Due</h2>${reportTable(['Employee','Item','Status','Replace Due','Notes'],due.map(i=>[esc(i.employee),esc(titleCase(i.item)),uniformStatusBadge(i.status),esc(fmtDate(i.replacementDue||'')),esc(i.notes||'')]))}</div>`;showReport('Uniform Status Report','Uniform issue, order, replacement, and exception accountability',body,'landscape',autoPrint)}
function reportTaskStatus(autoPrint=false){let list=(tasks.tasks||[]).slice();normalizeTasks();let open=list.filter(isTaskOpen);let overdue=open.filter(isTaskOverdue);let dueSoon=open.filter(isTaskDueSoon);let blocked=open.filter(t=>t.status==='Blocked');let rows=open.map(t=>[esc(t.project||''),esc(t.status||''),esc(t.priority||''),esc(t.category||''),esc(t.assignedTo||t.owner||''),esc(taskDateShort(t.dueDate)),esc(taskDateShort(t.followUpDate)),esc(t.blockedBy||''),esc(t.nextAction||''),esc(t.lastUpdate||t.update||'')]);let body=`<div class="report-section"><div class="report-summary"><strong>Executive Summary:</strong> ${open.length} active task(s) remain open. ${overdue.length} are overdue, ${dueSoon.length} are due or need follow-up within seven days, and ${blocked.length} are blocked.</div></div><div class="report-section">${reportKpis([{label:'Total Tasks',value:list.length},{label:'Open Tasks',value:open.length},{label:'Overdue',value:overdue.length},{label:'Due This Week',value:dueSoon.length},{label:'Blocked',value:blocked.length},{label:'High/Critical',value:open.filter(t=>['High','Critical'].includes(t.priority)).length}])}</div><div class="report-section"><h2>Open Task Detail</h2>${reportTable(['Project','Status','Priority','Category','Assigned To','Due','Follow-up','Blocked By','Next Action','Last Update'],rows)}</div>`;showReport('Task Status Report','Active project, follow-up, blocker, and weekly manager update status',body,'landscape',autoPrint)}
function reportAttendancePatterns(autoPrint=false){const open=attendancePatternFindings({includeAcknowledged:false});const hidden=acknowledgedPatternsList();const high=open.filter(p=>['High','Critical'].includes(p.risk));const rows=open.map(p=>[esc(p.emp.name),esc(p.emp.shift||''),esc(p.emp.title||''),esc(p.type),esc(p.risk||''),Number(p.score||0),esc(p.msg),esc(issueDateLabel(p.dates))]);const byShift={};open.forEach(p=>{const sh=p.emp.shift||'Unassigned';byShift[sh]=(byShift[sh]||0)+1});let body=`<div class="report-section"><div class="report-summary"><strong>Executive Summary:</strong> ${open.length} open attendance pattern(s) found. ${high.length} are High/Critical risk. ${hidden.length} acknowledged/monitored pattern record(s) are retained for history.</div></div><div class="report-section">${reportKpis([{label:'Open Patterns',value:open.length},{label:'High/Critical',value:high.length},{label:'Employees With Patterns',value:new Set(open.map(p=>String(p.emp.id))).size},{label:'Acknowledged History',value:hidden.length}])}</div><div class="report-section"><h2>Open Pattern Detail</h2>${reportTable(['Employee','Shift','Title','Pattern','Risk','Score','Reason','Dates'],rows)}</div><div class="report-section"><h2>Patterns by Shift</h2>${reportTable(['Shift','Open Patterns'],Object.entries(byShift).map(([k,v])=>[esc(k),v]))}</div><div class="report-section"><h2>Acknowledged / Monitored History</h2>${reportTable(['Employee','Pattern','Risk','Acknowledged','Note','Dates'],hidden.map(p=>[esc(p.empName||''),esc(p.type||''),esc(p.risk||''),esc(p.at||''),esc(p.note||''),esc(issueDateLabel(p.dates||[]))]))}</div>`;showReport('Attendance Pattern Report','Smart attendance pattern detection, risk score, acknowledged history, and shift exposure',body,'landscape',autoPrint)}

function executiveRiskLines(){const m=reportMetrics();const patterns=attendancePatternFindings({includeAcknowledged:false});const noticeK=noticeKpis();const si=siIssueMetrics();const pending=shiftIntelPendingCount();const openTasks=(tasks.tasks||[]).filter(isTaskOpen);const overdue=openTasks.filter(isTaskOverdue);const lines=[];if(Number(m.cov.total.openHours||0)>0)lines.push(['Staffing',`${m.cov.total.openHours} Open/Pending HPW remain on the published schedule.`,m.cov.total.highestRisk||'Schedule']);if(patterns.length)lines.push(['Attendance',`${patterns.length} unresolved attendance pattern(s), including ${patterns.filter(p=>['High','Critical'].includes(p.risk)).length} High/Critical.`,patterns[0]?.emp?.name||'Attendance Review']);if(noticeK.open)lines.push(['Notices',`${noticeK.open} open attendance notice(s) require workflow follow-up.`,'Notice Workflow']);if(Number(m.training.issueCount||0)>0)lines.push(['Training',`${m.training.issueCount} training readiness exception(s) are open.`,'Training']);if(Number(m.uniformNeeded||0)+Number(m.uniformDueSoon||0)>0)lines.push(['Uniforms',`${m.uniformNeeded} uniform item(s) needed and ${m.uniformDueSoon} replacement-due item(s).`,'Uniform Accountability']);if(si.needs||si.recurring||pending)lines.push(['Shift Intelligence',`${si.needs} Needs Action, ${si.recurring} Recurring, and ${pending} pending intake item(s).`,'Operations']);if(overdue.length)lines.push(['Tasks',`${overdue.length} overdue task(s) need owner follow-up.`,'Task Tracker']);if(!lines.length)lines.push(['Overall','No major open executive exceptions detected from current loaded data.','Monitor']);return lines}
function reportExecutiveBriefing(autoPrint=false){const m=reportMetrics();const si=siIssueMetrics();const nk=noticeKpis();const pending=shiftIntelPendingCount();const openTasks=(tasks.tasks||[]).filter(isTaskOpen);const overdue=openTasks.filter(isTaskOverdue);const patterns=attendancePatternFindings({includeAcknowledged:false});const risks=executiveRiskLines();let body=`<div class="report-section report-compact"><div class="report-summary"><strong>Executive Summary:</strong> Current command view shows ${m.active.length} active roster employee(s), ${m.cov.total.openHours} Open/Pending HPW, ${patterns.length} unresolved attendance pattern(s), ${nk.open} open notice(s), ${m.training.issueCount} training readiness exception(s), ${si.needs} Shift Intelligence Needs Action item(s), and ${overdue.length} overdue task(s). This package is designed for manager briefing, not raw data entry.</div>${reportMethodologyNote()}${reportAttendanceLegend()}</div><div class="report-section report-compact">${reportKpis([{label:'Active Headcount',value:m.active.length},{label:'Open/Pending HPW',value:m.cov.total.openHours},{label:'Attendance Patterns',value:patterns.length},{label:'Open Notices',value:nk.open},{label:'Training Issues',value:m.training.issueCount},{label:'SI Needs Action',value:si.needs},{label:'Pending Intake',value:pending},{label:'Overdue Tasks',value:overdue.length}])}</div>${reportDataConfidence(m)}<div class="report-section report-compact"><h2>Priority Briefing Lines</h2>${reportTable(['Area','Briefing Line','Where to Work It'],risks.map(r=>[esc(r[0]),esc(r[1]),esc(r[2])]))}</div><div class="report-section report-allow-break"><h2>Top Coverage / Attendance Exceptions</h2>${reportTable(['Area','Section','Post','Days','Required HPW','Named HPW','Open/Pending HPW','Missed HPW','No Entry HPW','Risk'],m.cov.rows.filter(r=>r.openHours>0||r.attendanceMissedHours>0||r.attendanceMissingHours>0).slice(0,20).map(r=>[esc(r.area),esc(r.section),esc(r.post||''),esc(r.dayLabel||''),r.requiredHours,r.scheduledHours,r.openHours,r.attendanceMissedHours||0,r.attendanceMissingHours||0,esc(r.risk)]))}</div><div class="report-section report-compact"><h2>Open Operational Work</h2>${reportTable(['Queue','Count','Action'],[['Shift Intelligence Needs Action',si.needs,'Review status, owner, recommended action, and next manager note'],['Shift Intelligence Recurring',si.recurring,'Decide whether to keep watching or move to Needs Action'],['Shift Intake Awaiting Review',pending,'Link/create/reference/ignore intake'],['Open Tasks',openTasks.length,'Work overdue, blocked, and due-soon items'],['Training Exceptions',m.training.issueCount,'Assign completions or verify records'],['Uniform Needed/Due',Number(m.uniformNeeded||0)+Number(m.uniformDueSoon||0),'Order, issue, replace, or close out records']].map(r=>[esc(r[0]),r[1],esc(r[2])]))}</div>`;showReport('Executive Operations Briefing','Command-level staffing, people, readiness, task, and operational intelligence summary',body,'landscape',autoPrint)}
function reportComplianceReadiness(autoPrint=false){const m=reportMetrics();const nk=noticeKpis();const patterns=attendancePatternFindings({includeAcknowledged:false});const active=activeRosterForReports();const topics=(roster.trainingTopics||[]).filter(t=>t.required!==false);let missingTraining=[];for(const e of active){for(const t of topics){const rec=latestTrainingRecord(e.id,t.id);const st=trainingStatus(rec,t);if(st!=='Complete')missingTraining.push([fullName(e),e.shift||'',t.name||'',st,rec&&rec.completed||'',rec&&rec.due||'']);}}const uniformItems=(typeof getUniformItems==='function')?getUniformItems('all'):[];const uniformExceptions=uniformItems.filter(i=>!['issued','returned','retired'].includes(i.status)||['due-soon','past-due'].includes(replacementDueClass(i.replacementDue)));const restoreReady=moduleFreshnessRows();let body=`<div class="report-section report-compact"><div class="report-summary"><strong>Executive Summary:</strong> Compliance readiness review shows ${nk.open} open notice(s), ${patterns.length} unresolved pattern item(s), ${missingTraining.length} required training exception(s), ${uniformExceptions.length} uniform accountability exception(s), and current live-data freshness markers listed below. Use this before audits, reviews, or executive updates.</div></div><div class="report-section report-compact">${reportKpis([{label:'Open Notices',value:nk.open},{label:'Refused Signatures',value:nk.refused},{label:'Escalated Notices',value:nk.escalated},{label:'Open Patterns',value:patterns.length},{label:'Training Exceptions',value:missingTraining.length},{label:'Uniform Exceptions',value:uniformExceptions.length},{label:'Backup Candidates',value:backupManager?Number(backupManager.totalCleanable||0):'Load Manager'}])}</div><div class="report-section"><h2>Attendance Notice Evidence</h2>${reportTable(['Employee','Date','Type','Status','Related Dates','Delivered','Response'],noticeRecords().filter(n=>!['Closed','Void','No Notice Needed'].includes(n.status||'')).map(n=>[esc(n.employeeName||attendanceEmployeeNameById(n.employeeId)),esc(fmtDate(n.date||'')),esc(n.noticeType||n.level||''),esc(n.status||''),esc((n.relatedDates||[]).map(fmt).join(', ')),esc(fmtDate(n.deliveredDate||'')),esc(n.employeeResponse||'')]))}</div><div class="report-section"><h2>Training Exceptions</h2>${reportTable(['Employee','Shift','Required Topic','Status','Completed','Due'],missingTraining.slice(0,120).map(r=>r.map(esc)))}</div><div class="report-section"><h2>Uniform Exceptions</h2>${reportTable(['Employee','Item','Status','Replacement Due','Notes'],uniformExceptions.map(i=>[esc(i.employee||''),esc(titleCase(i.item||'')),uniformStatusBadge(i.status),esc(fmtDate(i.replacementDue||'')),esc(i.notes||'')]))}</div><div class="report-section report-compact"><h2>Live Data / Backup Readiness</h2>${reportTable(['Module','Newest Meaningful Date','Status'],restoreReady.map(r=>[esc(r.label),esc(fmt(r.date||'')),esc(freshnessClass(r.date,r.warn,r.bad)||'ok')]))}</div>`;showReport('Compliance Readiness Report','Attendance evidence, readiness exceptions, uniform accountability, and live-data freshness',body,'landscape',autoPrint)}
function reportShiftIntelligenceSummary(autoPrint=false){normalizeShiftIntel();const im=siIssueMetrics();const bc=siBucketCounts();const active=(shiftIntel.issues||[]).filter(i=>!['Resolved','Ignored','Reference Only'].includes(i.status||'New'));const pending=(shiftIntel.intake||[]).filter(i=>(i.status||'Pending')==='Pending');const byCat={};active.forEach(i=>{byCat[i.category||'Uncategorized']=(byCat[i.category||'Uncategorized']||0)+1});const watch=active.slice().sort((a,b)=>['Needs Action','Recurring','New','Watching','Dormant'].indexOf(siComputedStatus(a))-['Needs Action','Recurring','New','Watching','Dormant'].indexOf(siComputedStatus(b))||String(b.lastSeen||'').localeCompare(String(a.lastSeen||'')));let body=`<div class="report-section report-compact"><div class="report-summary"><strong>Executive Summary:</strong> Shift Intelligence has ${im.active} active watchlist item(s), including ${im.needs} Needs Action, ${im.recurring} Recurring, and ${im.dormant} Dormant. Intake review has ${bc.pending} pending item(s): ${bc.auto} auto-link, ${bc.suggest} suggested, ${bc.new} new, and ${bc.ref} ignored/reference candidate(s).</div></div><div class="report-section report-compact">${reportKpis([{label:'Active Watchlist',value:im.active},{label:'Needs Action',value:im.needs},{label:'Recurring',value:im.recurring},{label:'Dormant',value:im.dormant},{label:'Pending Intake',value:bc.pending},{label:'Reference Items',value:(shiftIntel.reference||[]).length}])}</div><div class="report-section"><h2>Active Watchlist Detail</h2>${reportTable(['ID','Title','Category','Status','Priority','First Seen','Last Seen','Times','Owner','Recommended Action'],watch.map(i=>['SI-'+String(i.id).padStart(4,'0'),esc(i.title||''),esc(i.category||''),esc(siComputedStatus(i)),esc(i.priority||''),esc(fmtDate(i.firstSeen||'')),esc(fmtDate(i.lastSeen||'')),i.timesMentioned||1,esc(i.owner||''),esc(i.recommendedAction||'')]))}</div><div class="report-section report-compact"><h2>Active Issues by Category</h2>${reportTable(['Category','Active Issues'],Object.entries(byCat).sort((a,b)=>b[1]-a[1]).map(([k,v])=>[esc(k),v]))}</div><div class="report-section"><h2>Pending Intake</h2>${reportTable(['Bucket','Report','Date','Shift','Category','Title','Confidence','Recommended Action'],pending.slice(0,80).map(i=>[esc(i.bucket||''),esc(i.reportId||''),esc(fmtDate(i.date||'')),esc(i.shift||''),esc(i.category||''),esc(i.title||''),esc(i.confidence||''),esc(i.recommendedAction||'')]))}</div>`;showReport('Shift Intelligence Summary','Operational issue watchlist, intake buckets, recurrence, and manager action visibility',body,'landscape',autoPrint)}
function reportOperationsFullSummary(autoPrint=false){const m=reportMetrics();const si=siIssueMetrics();const bc=siBucketCounts();const sm=shiftReportMetrics();const openTasks=(tasks.tasks||[]).filter(isTaskOpen);const overdue=openTasks.filter(isTaskOverdue);let body=`<div class="report-section report-compact"><div class="report-summary"><strong>Executive Summary:</strong> Operations summary combines staffing, shift reports, Shift Intelligence, tasks, supplies, uniforms, and readiness exceptions. Current data shows ${m.cov.total.openHours} Open/Pending HPW, ${sm.open} open Shift Report issue(s), ${si.needs} Shift Intelligence Needs Action item(s), ${bc.pending} intake item(s), ${openTasks.length} open task(s), and ${overdue.length} overdue task(s).</div>${reportMethodologyNote()}</div><div class="report-section report-compact">${reportKpis([{label:'Open/Pending HPW',value:m.cov.total.openHours},{label:'Shift Reports Imported',value:sm.reports},{label:'Open Report Issues',value:sm.open},{label:'SI Needs Action',value:si.needs},{label:'Pending Intake',value:bc.pending},{label:'Open Tasks',value:openTasks.length},{label:'Overdue Tasks',value:overdue.length},{label:'Supply Exceptions',value:officeSupplyItems(false).filter(i=>['Low','Out','Ordered'].includes(officeSupplyStatus(i))).length}])}</div><div class="report-section"><h2>Command Queue Detail</h2>${reportTable(['Queue','Count','Recommended Use'],[['Coverage Gaps',m.cov.total.openPosts,'Review schedule authority and post coverage'],['Shift Report Open Issues',sm.open,'Close raw issue follow-ups or move meaningful items into Intelligence'],['Shift Intelligence Needs Action',si.needs,'Assign owner/action and manager note'],['Shift Intelligence Recurring',si.recurring,'Escalate or continue monitoring'],['Pending Intake',bc.pending,'Link/create/reference/ignore'],['Open Tasks',openTasks.length,'Update owner, due date, blocker, and current update'],['Uniform Needed',m.uniformNeeded,'Order/issue/replace'],['Training Issues',m.training.issueCount,'Schedule or verify training']].map(r=>[esc(r[0]),r[1],esc(r[2])]))}</div><div class="report-section"><h2>Open Tasks</h2>${reportTable(['Project','Status','Priority','Owner','Due','Next Action'],openTasks.map(t=>[esc(t.project||''),esc(t.status||''),esc(t.priority||''),esc(t.assignedTo||t.owner||''),esc(taskDateShort(t.dueDate)),esc(t.nextAction||t.update||'')]))}</div>`;showReport('Operations Full Summary','Staffing, reports, intelligence, tasks, supplies, uniforms, and readiness in one command report',body,'landscape',autoPrint)}
function runReport(type,autoPrint=false){if(!canAccessReports()){toast('Reports are Admin/Supervisor only');return;}({executive:reportExecutiveBriefing,compliance:reportComplianceReadiness,operations:reportOperationsFullSummary,shiftintel:reportShiftIntelligenceSummary,weekly:reportWeeklyStaffing,labor:reportLaborCost,coverage:reportCoverageGap,attendance:reportAttendanceSummary,patterns:reportAttendancePatterns,notices:reportAttendanceNotices,training:reportTrainingReadiness,uniforms:reportUniformStatus,supplies:reportOfficeSupplies,tasks:reportTaskStatus}[type]||reportWeeklyStaffing)(autoPrint)}
function viewReport(type){runReport(type,false)}
function printReport(type){runReport(type,true)}
function exportReportCSV(type){if(!canAccessReports()){toast('Reports are Admin/Supervisor only');return;}const date=new Date().toISOString().slice(0,10);const m=reportMetrics();let rows=[];if(type==='weekly'){rows=[['Metric','Value'],['Active Headcount',m.active.length],['Schedule Required HPW',m.cov.total.requiredHours],['Named Scheduled HPW',m.cov.total.scheduledHours],['Open/Pending HPW',m.cov.total.openHours],['Attendance Covered HPW',m.cov.total.attendanceCoveredHours],['Attendance Missed HPW',m.cov.total.attendanceMissedHours],['No Entry HPW',m.cov.total.attendanceMissingHours],[],['Area','Section','Post','Schedule Required HPW','Named Scheduled HPW','Open/Pending HPW','Attendance Covered HPW','Attendance Missed HPW','No Entry HPW','Risk'],...m.cov.rows.map(r=>[r.area,r.section,r.post||'',r.requiredHours,r.scheduledHours,r.openHours,r.attendanceCoveredHours||0,r.attendanceMissedHours||0,r.attendanceMissingHours||0,r.risk])];}
else if(type==='labor'){if(!canViewLaborSummary()){toast('Labor cost reports are restricted');return;}rows=[['Metric','Value'],['Loaded Weekly Cost',m.sched.loadedCost.toFixed(2)],['Loaded Monthly Run Rate',(m.sched.loadedCost*Number(settings.monthlyMultiplier||4.333)).toFixed(2)],['Loaded Annual Run Rate',(m.sched.loadedCost*Number(settings.annualMultiplier||52)).toFixed(2)],[],['Section','Assigned HPW','Required HPW','Gap HPW','Loaded Cost'],...Object.values(m.sched.sections).map(x=>[x.section,x.assignedHours,x.requiredHours,x.openHours,x.loadedCost.toFixed(2)])];}
else if(type==='coverage'){rows=[['Area','Section','Post','Days','Required HPW','Named Scheduled HPW','Gap HPW','Risk','Notes'],...m.cov.rows.filter(r=>r.openHours>0||['Short','No coverage'].includes(r.risk)).map(r=>[r.area,r.section,r.post||'',r.dayLabel||coverageDayLabel(r),r.requiredHours,r.scheduledHours,r.openHours,r.risk,r.notes||''])];}
else if(type==='attendance'){let r30=attendanceReportRows(30),r90=attendanceReportRows(90);rows=[['Code','Description','Last 30 Days','Last 90 Days'],...CODES.map(c=>[c[0],c[1],r30.counts[c[0]]||0,r90.counts[c[0]]||0])];}
else if(type==='notices'){rows=[['Employee','Shift','Date','Type','Subject','Level','Status','Related Dates','Pattern Type','Pattern Risk','Delivered Date','Delivered By','Employee Response','Manager Notes','Void Reason'],...noticeRecords().map(n=>[n.employeeName||attendanceEmployeeNameById(n.employeeId),n.employeeShift||'',n.date||'',n.noticeType||'',n.subject||'',n.level||'',n.status||'',(n.relatedDates||[]).join('; '),n.patternType||'',n.patternRisk||'',n.deliveredDate||'',n.deliveredBy||'',n.employeeResponse||'',n.managerNotes||'',n.voidReason||''])];}
else if(type==='patterns'){rows=[['Employee','Shift','Title','Pattern','Risk','Score','Reason','Dates'],...attendancePatternFindings({includeAcknowledged:false}).map(p=>[p.emp.name,p.emp.shift||'',p.emp.title||'',p.type,p.risk||'',p.score||0,p.msg,issueDateLabel(p.dates)])];}
else if(type==='training'){const active=activeRosterForReports();const topics=(roster.trainingTopics||[]).filter(t=>t.required!==false);rows=[['Employee','Shift','Topic','Status','Completed','Due']];for(const e of active){for(const t of topics){const rec=latestTrainingRecord(e.id,t.id);const st=trainingStatus(rec,t);if(st!=='Complete')rows.push([fullName(e),e.shift||'',t.name||'',st,rec&&rec.completed||'',rec&&rec.due||'']);}}}
else if(type==='uniforms'){const items=(typeof getUniformItems==='function')?getUniformItems('all'):[];rows=[['Employee','Rank','Shift','Item','Size/ID','Status','Qty','Order Date','Issue Date','Replacement Due','Cost','Notes'],...items.map(i=>[i.employee,i.rank,i.shift,i.item,i.size,i.status,i.qty,i.orderDate||'',i.issueDate||'',i.replacementDue||'',i.cost||'',i.notes||''])];}
else if(type==='supplies'){const items=officeSupplyItems(true);rows=[['Item','Category','Current Qty','Minimum Qty','Order Qty','Status','Last Ordered','Last Received','Vendor','Storage Location','Cost','Notes','Archived'],...items.map(i=>[i.item||'',i.category||'',i.qty||0,i.minQty||0,i.orderQty||0,officeSupplyStatus(i),i.lastOrdered||'',i.lastReceived||'',i.vendor||'',i.location||'',i.cost||'',i.notes||'',i.archived?'Yes':'No'])];}
else if(type==='tasks'){rows=[['Project','Status','Priority','Category','Owner','Due','Current Update'],...(tasks.tasks||[]).map(t=>[t.project||'',t.status||'',t.priority||'',t.category||'',t.owner||'',t.dueDate||'',t.update||''])];}
else if(type==='executive'){rows=[['Area','Briefing Line','Where to Work It'],...executiveRiskLines()];}
else if(type==='compliance'){const nk=noticeKpis();rows=[['Metric','Value'],['Open Notices',nk.open],['Escalated Notices',nk.escalated],['Refused Signatures',nk.refused],['Open Attendance Patterns',attendancePatternFindings({includeAcknowledged:false}).length],['Training Issues',reportMetrics().training.issueCount],['Uniform Needed',reportMetrics().uniformNeeded]];}
else if(type==='shiftintel'){normalizeShiftIntel();rows=[['ID','Title','Category','Status','Priority','First Seen','Last Seen','Times Mentioned','Owner','Recommended Action'],...(shiftIntel.issues||[]).map(i=>['SI-'+String(i.id).padStart(4,'0'),i.title||'',i.category||'',siComputedStatus(i),i.priority||'',i.firstSeen||'',i.lastSeen||'',i.timesMentioned||1,i.owner||'',i.recommendedAction||''])];}
else if(type==='operations'){const m=reportMetrics(),sm=shiftReportMetrics(),si=siIssueMetrics(),bc=siBucketCounts();rows=[['Metric','Value'],['Open/Pending HPW',m.cov.total.openHours],['Shift Reports Imported',sm.reports],['Open Shift Report Issues',sm.open],['Shift Intelligence Needs Action',si.needs],['Shift Intake Pending',bc.pending],['Open Tasks',(tasks.tasks||[]).filter(isTaskOpen).length],['Training Issues',m.training.issueCount],['Uniform Needed',m.uniformNeeded]];}
downloadCSV('PWADC_'+type+'_Report_'+date+'.csv',rows);toast('Exported '+type+' report CSV')}

