function escAttr(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');}


function moduleIncludedCard(title,desc,actions){return `<div class="card module-card"><h3>${esc(title)}</h3><p>${esc(desc)}</p>${actions?`<div class="toolbar" style="margin-top:12px">${actions}</div>`:''}</div>`}

const SCREEN_GUIDES={
  'home':{title:'Command Center',text:'Start here. Work only the visible priority queues first, then open secondary signals if you need more detail.',steps:['Review priorities','Open queue','Clear decision']},
  'start-here':{title:'Operating Guide',text:'Use this page as the plain-English map for the suite. It explains the daily order of work without digging through every module.',steps:['Read flow','Open module','Print if needed']},
  'attendance':{title:'Attendance Workflow',text:'Start with daily codes, then move to review, patterns, and notices only when the evidence supports a decision.',steps:['Daily entry','Review exceptions','Pattern decision','Notice / monitor']},
  'roster':{title:'People Data Hub',text:'Roster is the source for employee identity, schedule authority, training, uniforms, and labor analytics.',steps:['Find employee','Update record','Check related tabs']},
  'employee-profile':{title:'Employee Snapshot',text:'Use this as the one-person command view before opening the source module for roster, attendance, training, uniform, or schedule action.',steps:['Search employee','Review command tiles','Open source module']},
  'training':{title:'Training Readiness',text:'Work missing, expired, expiring, and post-readiness exceptions first, then record optional completions as supporting history.',steps:['Filter exceptions','Update record','Recheck employee readiness']},
  'office-supplies':{title:'Supply Control',text:'Keep office/security supplies simple: low stock, out, ordered, received, vendor, and storage location.',steps:['Review low/out','Update qty','Print/export']},
  'tasks':{title:'Task Command Board',text:'Use this as the follow-up endpoint for projects, blockers, due dates, and weekly updates.',steps:['Review overdue','Update next action','Generate draft']},
  'shift-reports':{title:'Report Intake',text:'Import and preserve raw shift reports here. Send meaningful items to Shift Intelligence for long-term decisions.',steps:['Import PDF','Store source','Review in intelligence']},
  'shift-intelligence':{title:'Issue Decision Layer',text:'Convert report mentions into controlled operational decisions: link, create, reference, ignore, watch, or resolve.',steps:['Review intake','Decide bucket','Work watchlist','Resolve deliberately']},
  'reports':{title:'Report Center',text:'Select the management decision first, then confirm scope, preview the finished output, and publish.',steps:['Select report','Confirm scope','Preview','Publish']},
  'data-health':{title:'Data Health',text:'Use integrity findings as the control gate before reporting, repair, cleanup, or restore.',steps:['Run check','Review severity','Verify files','Act carefully']},
  'restore':{title:'Guarded Restore',text:'Select the exact data boundary, preview the backup, document the reason, and verify after replacement.',steps:['Select scope','Choose backup','Preview','Restore']},
  'change-log':{title:'Audit Trail',text:'Review who changed what and work high-impact entries before routine activity.',steps:['Filter module','Search activity','Review impact','Document']},
  'other-programs':{title:'Standalone Tools',text:'Launch specialized audit tools without mixing them into daily suite data.',steps:['Pick tool','Launch','Return to suite']},
  'settings':{title:'Admin Settings',text:'Manage one control area at a time, understand the operational impact, then validate and save once.',steps:['Choose section','Review impact','Edit','Save']}
};
function screenGuide(key){
  const g=SCREEN_GUIDES[key]||{title:'Screen Guide',text:'Use this screen from left to right: review the summary, apply filters, then take the needed action.',steps:['Review','Filter','Act']};
  const steps=(g.steps||[]).map((x,i)=>`<span class="screen-step ${i===0?'primary-step':''}"><span class="step-index">${i+1}</span>${esc(x)}</span>`).join('');
  return `<div class="screen-guide"><div class="screen-guide-title">${esc(g.title)}</div><div class="screen-guide-text">${esc(g.text)}</div>${steps?`<div class="screen-guide-steps">${steps}</div>`:''}</div>`;
}
